var request = new HttpRequestMessage
{
    Method = HttpMethod.Post,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/companies/%7Bcompany_id%7D/projects/%7Bproject_id%7D/currency_configuration"),
    Content = new StringContent("{\"currency_iso_code\":\"USD\",\"company_currency_exchange_rate_override\":\"1.2\",\"currency_display\":\"symbol\",\"multicurrency_enabled\":true}")
